/// <summary>
///     The <c>AVAInventTransferUpdShipCls_Extension</c> is the execution class for class <c>InventTransferUpdShip</c>
/// </summary>
[ExtensionOf(classStr(InventTransferUpdShip))]
final class AVAInventTransferUpdShipCls_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>updateInventTransferLine</c> method.
/// </summary>
/// <param name="_inventTransferParmLine">
///    <c>InventTransferParmLine</c> as type
/// </param>
protected void updateInventTransferLine(InventTransferParmLine  _inventTransferParmLine)
{
    InventTransferLine locInventTransferLine;

    next updateInventTransferLine(_inventTransferParmLine);

    ttsbegin;
    locInventTransferLine = InventTransferLine::findTransIdShip(_inventTransferParmLine.InventTransId, true);
    if (locInventTransferLine.RecId)
    {
        if (locInventTransferLine.QtyRemainShip > 0.0 && locInventTransferLine.KCS_SOCPickingReleaseIndicator)
        {
            locInventTransferLine.KCS_SOCPickingReleaseIndicator = NoYes::No;
            locInventTransferLine.update();
        }
    }
    ttscommit;
}
